//! Independent native event grammar and byte splits; not generated by the codec.
use morphiecore::{
    execution::Attempt,
    protocol::{
        anthropic::{MessageSseDecoder, Profile, ReplayTarget},
        openai::sse::{SseError, SseLimits},
    },
    semantic::task::generation::LocalScope,
};
use serde_json::{Value, json};
fn frames() -> Vec<Value> {
    vec![
        json!({"type":"message_start","message":{"id":"msg","type":"message","role":"assistant","model":"synthetic-model",
            "content":[],"stop_reason":null,"stop_sequence":null,"usage":{"input_tokens":11,"output_tokens":0,
                "cache_creation_input_tokens":4,"cache_read_input_tokens":3}}}),
        json!({"type":"ping"}),
        json!({"type":"content_block_start","index":0,"content_block":{"type":"thinking","thinking":"","signature":""}}),
        json!({"type":"content_block_delta","index":0,"delta":{"type":"thinking_delta","thinking":"雪"}}),
        json!({"type":"content_block_delta","index":0,"delta":{"type":"signature_delta","signature":"sig-"}}),
        json!({"type":"content_block_delta","index":0,"delta":{"type":"signature_delta","signature":"tail"}}),
        json!({"type":"content_block_stop","index":0}),
        json!({"type":"content_block_start","index":1,"content_block":{"type":"text","text":""}}),
        json!({"type":"content_block_delta","index":1,"delta":{"type":"text_delta","text":"ok"}}),
        json!({"type":"content_block_stop","index":1}),
        json!({"type":"content_block_start","index":2,"content_block":{"type":"tool_use","id":"toolu_one","name":"lookup","input":{}}}),
        json!({"type":"content_block_delta","index":2,"delta":{"type":"input_json_delta","partial_json":"{\"z\":1.000000000000000001"}}),
        json!({"type":"content_block_delta","index":2,"delta":{"type":"input_json_delta","partial_json":",\"a\":\"v\"}"}}),
        json!({"type":"content_block_stop","index":2}),
        json!({"type":"message_delta","delta":{},"usage":{"output_tokens":7}}),
        json!({"type":"message_delta","delta":{"stop_reason":"tool_use","stop_sequence":null},"usage":{"output_tokens":9}}),
        json!({"type":"message_stop"}),
    ]
}
fn wire(frames: &[Value]) -> Vec<u8> {
    frames
        .iter()
        .map(|v| format!("event: {}\ndata: {v}\n\n", v["type"].as_str().unwrap()))
        .collect::<String>()
        .into_bytes()
}
fn feed(d: &mut MessageSseDecoder, mut bytes: &[u8]) -> Result<(), SseError> {
    while !bytes.is_empty() {
        let used = d.consume(bytes)?;
        assert!(used > 0);
        bytes = &bytes[used..];
    }
    Ok(())
}
fn expected() -> Value {
    serde_json::from_str(r#"{"id":"msg","type":"message","role":"assistant","model":"synthetic-model",
        "content":[{"type":"thinking","thinking":"雪","signature":"sig-tail"},{"type":"text","text":"ok"},
            {"type":"tool_use","id":"toolu_one","name":"lookup","input":{"z":1.000000000000000001,"a":"v"}}],
        "stop_reason":"tool_use","stop_sequence":null,"usage":{"input_tokens":11,"output_tokens":9,
            "cache_creation_input_tokens":4,"cache_read_input_tokens":3}}"#).unwrap()
}
#[test]
fn native_message_and_byte_splits_share_an_independent_static_oracle() {
    let bytes = wire(&frames());
    for split in 0..=bytes.len() {
        let mut decoder = MessageSseDecoder::new(
            200,
            "text/event-stream; charset=utf-8",
            SseLimits::default(),
        )
        .unwrap();
        feed(&mut decoder, &bytes[..split]).unwrap();
        feed(&mut decoder, &bytes[split..]).unwrap();
        let message = decoder.finish().unwrap();
        assert_eq!(
            Profile::AdaptiveTextTools
                .encode_response(&message)
                .unwrap(),
            expected()
        );
        assert!(decoder.finish().is_err());
    }
    let mut decoder =
        MessageSseDecoder::new(200, "text/event-stream", SseLimits::default()).unwrap();
    for byte in &bytes {
        feed(&mut decoder, std::slice::from_ref(byte)).unwrap();
    }
    assert_eq!(
        Profile::AdaptiveTextTools
            .encode_response(&decoder.finish().unwrap())
            .unwrap(),
        expected()
    );
}
#[test]
fn malformed_unclosed_or_trailing_streams_never_recover_success() {
    let original = frames();
    let mut cases = Vec::new();
    for index in [0, 6, 9, 13, 16] {
        let mut v = original.clone();
        v.remove(index);
        cases.push(v);
    }
    let mut v = original.clone();
    v[11]["delta"]["partial_json"] = json!("{\"z\":1,\"z\":2");
    cases.push(v);
    let mut v = original.clone();
    v[11]["delta"]["partial_json"] = json!("{\"z\":1");
    v.remove(12);
    cases.push(v);
    let mut v = original.clone();
    v[12]["delta"]["type"] = json!("text_delta");
    cases.push(v);
    let mut v = original.clone();
    v[7]["index"] = json!(0);
    cases.push(v);
    let mut v = original.clone();
    v[4]["index"] = json!(1);
    cases.push(v);
    let mut v = original.clone();
    v.insert(6, original[3].clone());
    cases.push(v);
    let mut v = original.clone();
    v[2]["content_block"]["signature"] = json!("opening-signature");
    cases.push(v);
    let mut v = original.clone();
    v[10]["content_block"]["input"] = json!({"key":"not-an-opening-fragment"});
    cases.push(v);
    let mut v = original.clone();
    v.insert(7, original[6].clone());
    cases.push(v);
    for at in [1, 16, 17] {
        let mut v = original.clone();
        v.insert(
            at,
            json!({"type":"error","error":{"type":"overloaded_error","message":"synthetic"}}),
        );
        cases.push(v);
    }
    let mut v = original.clone();
    v.push(json!({"type":"ping"}));
    cases.push(v);
    for case in cases {
        let mut d = MessageSseDecoder::new(200, "text/event-stream", SseLimits::default()).unwrap();
        let failed = feed(&mut d, &wire(&case)).is_err();
        assert!(failed || d.finish().is_err());
        assert!(feed(&mut d, &wire(&original)).is_err());
    }
    let mut d = MessageSseDecoder::new(200, "text/event-stream", SseLimits::default()).unwrap();
    let mut truncated = wire(&original);
    truncated.truncate(truncated.len() - 2);
    feed(&mut d, &truncated).unwrap();
    assert!(d.finish().is_err());
}
#[test]
fn limits_http_and_attempt_cancellation_are_independent_boundaries() {
    assert!(MessageSseDecoder::new(201, "text/event-stream", SseLimits::default()).is_err());
    assert!(
        MessageSseDecoder::new(
            200,
            "text/event-stream; charset=latin1",
            SseLimits::default()
        )
        .is_err()
    );
    let bytes = wire(&frames());
    for limits in [
        SseLimits {
            max_wire_bytes: bytes.len() - 1,
            ..SseLimits::default()
        },
        SseLimits {
            max_event_bytes: 64,
            ..SseLimits::default()
        },
        SseLimits {
            max_events: 2,
            ..SseLimits::default()
        },
    ] {
        let mut d = MessageSseDecoder::new(200, "text/event-stream", limits).unwrap();
        assert!(feed(&mut d, &bytes).is_err());
        assert!(d.finish().is_err());
    }
    let p = Profile::AdaptiveTextTools;
    let target = ReplayTarget::new("synthetic-provider", "synthetic-model").unwrap();
    let source=p.decode_generation_request(br#"{"model":"synthetic-model","max_tokens":32,"messages":[{"role":"user","content":"go"}]}"#,LocalScope::new(1),&target).unwrap();
    let mut a =
        Attempt::native_messages(source.clone(), target.clone(), LocalScope::new(2), 2 << 20)
            .unwrap();
    a.begin(200, "text/event-stream").unwrap();
    let mut offset = 0;
    while offset < bytes.len() {
        let (n, events) = a.push(&bytes[offset..]).unwrap();
        assert!(events.is_empty());
        offset += n;
    }
    assert!(a.response().is_err());
    let expected = p
        .decode_generation_response(
            &expected().to_string().into_bytes(),
            LocalScope::new(2),
            &source,
            &target,
        )
        .unwrap();
    assert_eq!(a.finish().unwrap(), &expected);
    let mut a = Attempt::native_messages(source, target, LocalScope::new(2), 2 << 20).unwrap();
    a.begin(200, "text/event-stream").unwrap();
    a.push(&bytes[..100]).unwrap();
    a.cancel();
    assert!(a.push(&bytes).is_err());
    assert!(a.finish().is_err());
}
